#!/bin/sh
# k1.sh - K1 container lifecycle (round-5 image, a long-lived container pinned to one CPU).
# usage: k1.sh start <cpu> | stop | warm
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'live-host-measurement-confounds/k1.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'k1.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
if [ "${1:-}" = "--help" ] || [ "${1:-}" = "-h" ]; then
  echo "usage: k1.sh start <cpu> | stop | warm"
  echo "       k1.sh --help | --build | --version"
  echo "start  create container lhmc-k1 from image lhmc-r5 (round-5 toolchain image) with --cpuset-cpus <cpu>,"
  echo "       --cgroup-parent lhmc.slice, --cap-add PERFMON (plus SYS_ADMIN while perf_event_paranoid > 2),"
  echo "       MEASURE_ROWS=200000, MEASURE_DATA_CACHE=/tmp/r5cache"
  echo "warm   one untimed invocation to fill the dataset cache"
  echo "stop   remove the container"
  exit 0
fi
set -eu


HERE=$(cd "$(dirname "$0")" && pwd)
case ${1:-} in
  --build|--version) exec "$HERE/ctl" --build ;;
  start)
    cpu=${2:?cpu (a CPU list, or none for an unpinned container)}
    caps="--cap-add PERFMON"
    [ "$(cat /proc/sys/kernel/perf_event_paranoid)" -le 2 ] || caps="$caps --cap-add SYS_ADMIN"
    pinarg="--cpuset-cpus $cpu"; [ "$cpu" != none ] || pinarg=""
    # shellcheck disable=SC2086
    docker run -d --name lhmc-k1 --cgroup-parent lhmc.slice $pinarg $caps \
      -e MEASURE_ROWS=200000 -e MEASURE_DATA_CACHE=/tmp/r5cache lhmc-r5 sleep infinity >/dev/null ;;
  warm)
    docker exec -e MEASURE_PAD=0 -e MEASURE_PERF=1 lhmc-k1 python3 measure_one.py r5/c-gcc-O2-L0/parse_number.so mixed >/dev/null ;;
  stop) docker rm -f lhmc-k1 >/dev/null 2>&1 || true ;;
  *) echo "k1.sh: unknown command '${1:-}' (try --help)" >&2; exit 2 ;;
esac
